using System;using System.IO;using System.Linq;using System.Collections.Generic;using Newtonsoft.Json;using Newtonsoft.Json.Linq;using Spacewars.Runtime;using Spacewars.Simulation;
internal static class FormationBankPreparation
{
    static NavPoint Point(JToken x)=>new NavPoint((double)x["X"],(double)x["Z"]);
    static void Check(bool x,string why){if(!x)throw new InvalidOperationException(why);}
    internal static void Run()
    {
        string input=Environment.GetEnvironmentVariable("RECAST_BANK_INPUT")??throw new ArgumentException("Saved input required"),output=Environment.GetEnvironmentVariable("RECAST_BANK_OUTPUT")??throw new ArgumentException("Unique output required");Check(!Directory.Exists(output),"Do not overwrite qualification");Directory.CreateDirectory(output);
        using var saved=WorldWire.Unpack(File.ReadAllBytes(Path.Combine(input,"terminal-nav14.bin")),WorldWire.ReadNavigationSessionState);var dto=saved.NavigationGeometry??saved.Geometry;var geometry=new NavGeometry(dto.HalfExtent,dto.Obstacles,dto.Revision);var profile=PlayableProfile.RecastGroupCorridorDefault;var formation=JObject.Parse(File.ReadAllText(Path.Combine(input,"formation-observation.json")));var mapping=formation["Mapping"];var frames=JArray.Parse(File.ReadAllText(Path.Combine(input,"frames.json")));double radius=(double)mapping["Spines"][0]["Radius"],pitch=profile.Navigation.ArrivalSlotSpacing;string binding=(string)mapping["Spines"][0]["ProviderBinding"],bank="bank/east";
                var budget=new NavigationRetentionBudget();Check(budget.TryOpenScope(NavigationPreparationKind.Admission,805,0,out var scope),"Owned scope refused");var results=new List<object>();
        using(scope){var r=scope.OwnedReservation();var provider=PartitionNavigationProvider.CopyOwned(new PartitionNavigationProvider(profile.AuthoredMap,geometry,(string)mapping["Spines"][0]["KnowledgeBinding"]),r);try{
            Check(provider.Binding==binding,"Saved exact provider binding changed");var seam=provider.Seams.Single(x=>x.Id==(string)mapping["EntryPortal"]);var exit=provider.Seams.Single(x=>x.Id==(string)mapping["ExitPortal"]);var start=new NavPoint((seam.From.X+seam.To.X)/2,(seam.From.Z+seam.To.Z)/2);var end=new NavPoint((exit.From.X+exit.To.X)/2,(exit.From.Z+exit.To.Z)/2);double dx=end.X-start.X,dz=end.Z-start.Z,length=Math.Sqrt(dx*dx+dz*dz);var direction=new NavPoint(dx/length,dz/length);var normal=new NavPoint(-direction.Z,direction.X);double low=double.NegativeInfinity,high=double.PositiveInfinity;
            foreach(var s in new[]{seam,exit}){double a=(s.From.X-start.X)*normal.X+(s.From.Z-start.Z)*normal.Z,b=(s.To.X-start.X)*normal.X+(s.To.Z-start.Z)*normal.Z;low=Math.Max(low,Math.Min(a,b)+radius);high=Math.Min(high,Math.Max(a,b)-radius);}
            var layout=new RecastFormationGuide.Layout(start,end,direction,length,low,high,pitch,radius);int window=Math.Max(1,(int)Math.Floor(length/pitch));var roles=mapping["Rows"].ToArray();Check(roles.Length==50&&layout.Lanes==3,"Saved50/lanes mismatch");
            foreach(long tick in new[]{(long)mapping["Tick"],2200L,2701L}){
                var frame=frames.Single(f=>(long)f["Tick"]==tick);var bodies=frame["Bodies"].ToDictionary(b=>(int)b["Id"]);var aggregate=formation["Frames"].First(f=>(long)f["Tick"]==tick);Check((int)aggregate["Tombstones"]==0,"This qualification requires recorded no-tombstone case");int firstOrdinal=50-(int)aggregate["Staging"],firstRow=firstOrdinal/layout.Lanes,recovering=(int)aggregate["Recovering"];double rear=roles.Where(e=>(int)e["EntryOrdinal"]>=recovering&&(int)e["EntryOrdinal"]<firstOrdinal).Min(e=>layout.Station(Point(bodies[(int)e["Entity"]]["Position"]))),frontier=Math.Min(-pitch,rear-pitch);var first=roles.Where(e=>(int)e["EntryOrdinal"]/layout.Lanes==firstRow&&(string)bodies[(int)e["Entity"]]["Location"]["SurfaceId"]==bank).ToArray();double clip=Math.Max(-pitch,first.Length==0?double.NegativeInfinity:first.Max(e=>layout.Station(Point(bodies[(int)e["Entity"]]["Position"]))));var attempts=new List<object>();List<object> accepted=null;var certifiedIds=new HashSet<int>();int capacity=0;
                for(int count=window;count>=1;count--){var selected=roles.Where(e=>(int)e["EntryOrdinal"]/layout.Lanes>=firstRow&&(int)e["EntryOrdinal"]/layout.Lanes<firstRow+count&&(string)bodies[(int)e["Entity"]]["Location"]["SurfaceId"]==bank).ToArray();if(selected.Length==0)continue;double front=Math.Max(frontier,selected.Max(e=>layout.Station(Point(bodies[(int)e["Entity"]]["Position"]))+((int)e["EntryOrdinal"]/layout.Lanes-firstRow)*pitch));bool valid=front<=clip+1e-9;var targets=new List<object>();var available=new HashSet<int>();var prior=new List<NavPoint>();
                    foreach(var e in selected){int id=(int)e["Entity"],role=(int)e["EntryOrdinal"]/layout.Lanes;var body=bodies[id];var from=new NavLocation(Point(body["Position"]),(string)body["Location"]["SurfaceId"]);double station=front-(role-firstRow)*pitch;var target=layout.Point(station,(int)e["Lane"]);var clearance=new NavClearanceProfile("ground",1,"ground",(int)e["Mobility"],(double)body["Radius"]);bool traceOk=provider.TryTraceOwned(from,target,clearance,out var reached,out var trace,r);try{traceOk&=reached.SurfaceId==bank&&trace!=null&&trace.All(l=>l.Kind==NavTypedLegKind.Surface&&l.From.SurfaceId==bank&&l.To.SurfaceId==bank);}finally{(trace as NavOwnedStorage)?.ReleaseOwner();}
                        bool footprint=provider.IsValid(new NavLocation(target,bank),clearance)&&geometry.IsFree(target,(double)body["Radius"]);bool forward=station+1e-9>=layout.Station(from.Position);bool spacing=prior.All(p=>Math.Pow(p.X-target.X,2)+Math.Pow(p.Z-target.Z,2)>=pitch*pitch-1e-9);var occupants=bodies.Values.Where(b=>(int)b["Id"]!=id&&Math.Pow((double)b["Position"]["X"]-target.X,2)+Math.Pow((double)b["Position"]["Z"]-target.Z,2)<Math.Pow((double)b["Radius"]+(double)body["Radius"],2)-1e-9).Select(b=>(int)b["Id"]).ToArray();bool certified=traceOk&&footprint&&forward&&spacing&&occupants.Length==0;if(certified)available.Add(id);valid&=forward&&spacing;targets.Add(new{Certified=certified,Entity=id,Role=role,Lane=(int)e["Lane"],Target=target,Station=station,FullOwnedSameBankTrace=traceOk,Footprint=footprint,Forward=forward,PitchSpacing=spacing,CurrentOccupants=occupants});prior.Add(target);
                    }
                    valid&=available.Count>0;attempts.Add(new{Available=available.Count,Rows=count,Front=front,EntrySideClip=clip,Valid=valid,Targets=targets});if(valid){capacity=count;accepted=targets;certifiedIds=available;break;}
                }
                var assignments=roles.Select(e=>new{Entity=(int)e["Entity"],Rank=(int)e["EntryOrdinal"],OriginalGoal=bodies[(int)e["Entity"]]["Goal"],Assigned=bodies[(int)e["Entity"]]["Assigned"],CurrentValid=provider.IsValid(new NavLocation(Point(bodies[(int)e["Entity"]]["Position"]),(string)bodies[(int)e["Entity"]]["Location"]["SurfaceId"]),new NavClearanceProfile("ground",1,"ground",0,radius)),Disposition=(int)e["EntryOrdinal"]<firstOrdinal?"Existing admitted/recovering unchanged":(certifiedIds.Contains((int)e["Entity"])?"Certified finite bank preparation":"Unchanged valid wide Wait")}).ToArray();Check(assignments.All(a=>a.CurrentValid),"Saved current footprint invalid");results.Add(new{Tick=tick,Window=window,FirstRow=firstRow,CapacityRows=capacity,CapacityActors=certifiedIds.Count,Attempts=attempts,Assignments=assignments,Targets=accepted});Console.WriteLine(JsonConvert.SerializeObject(new{Tick=tick,CapacityRows=capacity,CapacityActors=certifiedIds.Count,Provider=provider.Binding,Meaning="Saved frames/owned provider only; no World/Move/Step/native query"}));
            }
        }finally{((INavStorageFacade)provider).StorageRoot.Release();}scope.Discard();}
        Check(budget.PhysicalBytes==0&&budget.HeldBytes==0&&budget.ActiveScopes==0,"Owned geometry qualification leak");File.WriteAllText(Path.Combine(output,"bank-qualification.json"),JsonConvert.SerializeObject(new{Source=Environment.GetEnvironmentVariable("SPACEWARS_QA_SOURCE"),Input=input,Binding=binding,GeometryRevision=dto.Revision,Radius=radius,Pitch=pitch,Results=results,Census=new{budget.PhysicalBytes,budget.HeldBytes,budget.ActiveScopes},NoWorldMoveStepNativeQuery=true},Formatting.Indented));
    }
}
